class Session:
    def rebuild_proxies(self, prepared_request, proxies):
        headers = prepared_request.headers
        scheme = prepared_request.url.split(':')[0].lower()
        try:
            username, password = get_auth_from_url(proxies.get(scheme))
        except KeyError:
            username, password = None, None

        # Avoid appending this to TLS tunneled requests where it may be leaked.
        if not scheme.startswith('https') and username and password:
            headers["Proxy-Authorization"] = _basic_auth_str(username, password)

        return proxies

class SessionRedirectMixin:
    def should_strip_auth(self, old_url, new_url):
        original_parsed = urlparse(old_url)
        redirect_parsed = urlparse(new_url)

        if original_parsed.hostname != redirect_parsed.hostname:
            return True

        if original_parsed.port != redirect_parsed.port:
            return True
        return False

