def safe_join(directory, *pathnames):
    parts = [directory]
    for path in pathnames:
        path = path.replace("\\", "/")
        if path.startswith("/"):
            raise ValueError("Absolute paths not allowed")
        parts.append(path)
    return os.path.join(*parts)

