class PythonAstAnalyzer:
    def extract_affected_lines(self, file_diff):
        affected_lines = set()
        for hunk in file_diff.hunks:
            # Inspect deleted lines to detect affected symbols in deletions
            for old_line in range(hunk.old_start, hunk.old_start + hunk.old_count):
                affected_lines.add(old_line)
        return affected_lines
